import { toMoneyString } from "../helpers/currency";

export interface LiquidProduct {
  name: string;
  variants: LiquidVariant[];
}

export interface LiquidVariant {
  id: string;
  description: string;
  options: string[];
  price: string;
  compare_at_price: string | null;
  featured_media: {
    position: number;
  };
  available: boolean;
}

interface IProduct extends HTMLElement {
  selectedVariantId: string | null;
  setSelectedVariantId(variantId: string): void;
}

export class Product extends HTMLElement implements IProduct {
  private _selectedVariant: LiquidVariant | null = null;

  private _product: LiquidProduct | null = null;

  constructor() {
    super();
  }

  static get observedAttributes() {
    return ["selected-variant-id"];
  }

  connectedCallback() {
    this.loadProductData();
  }

  attributeChangedCallback(
    name: string,
    oldValue: string | null,
    newValue: string | null,
  ) {
    if (name === "selected-variant-id" && oldValue !== newValue) {
      this.updateSelectedVariant(newValue);
      this.updateProductDetails();
    }
  }

  get selectedVariantId(): string | null {
    return this.getAttribute("selected-variant-id");
  }

  set selectedVariantId(value: string | null) {
    if (value !== null) {
      this.setAttribute("selected-variant-id", value);
    } else {
      this.removeAttribute("selected-variant-id");
    }
  }

  public setSelectedVariantId(variantId: string): void {
    this.selectedVariantId = variantId;
  }

  get selectedVariant(): LiquidVariant | null {
    return this._selectedVariant;
  }

  private loadProductData(): void {
    const productJson = this.getAttribute("product");
    if (productJson) {
      try {
        this._product = JSON.parse(productJson);
      } catch (e) {
        console.error("Error parsing product data:", e);
      }
    } else {
      console.error("Product attribute is missing or empty");
    }
  }

  private updateSelectedVariant(variantId: string | null): void {
    if (!this._product || !this._product.variants) {
      console.error("No product or variants available");
      return;
    }
    const variant = this._product.variants.find(
      (v) => String(v.id) === variantId,
    );
    if (variant) {
      this._selectedVariant = variant;
    } else {
      console.error("Variant with id", variantId, "not found");
    }
  }

  private updateProductDetails(): void {
    if (!this._selectedVariant) {
      console.error("No selected variant available");
      return;
    }

    // Target spans to update product details based on selected variant
    const { price, compare_at_price, available } = this._selectedVariant;

    const productDetails = {
      price: this.querySelector("[data-price]"),
      comparePrice: this.querySelector("[data-compare-at-price]"),
      addToCartButton: this.querySelector("[data-add-to-cart]"),
    };

    if (productDetails.price) {
      productDetails.price.textContent = toMoneyString(price);
    }

    if (productDetails.comparePrice) {
      productDetails.comparePrice.textContent = compare_at_price
        ? toMoneyString(compare_at_price)
        : "";
    }

    if (productDetails.addToCartButton) {
      productDetails.addToCartButton.toggleAttribute("disabled", !available);
    }
  }
}

customElements.define("uwp-product", Product);
