/**
 * Converts an amount into a money formatted string.
 * @param amount - The amount to convert, as a string or number.
 * @param cents - OPTIONAL: Whether or not the amount is already in cents. Default: true.
 * @returns The amount in money formatted string.
 * @example
 * toMoneyString(100);
 * // '$1.00'
 * toMoneyString(100, false);
 * // '$100.00'
 */
export function toMoneyString(amount: string | number, cents = true): string {
  let newAmount = amount;
  if (!cents) {
    newAmount = toCents(amount);
  }
  const moneyAmount: string = (parseFloat(newAmount as string) / 100).toFixed(
    2,
  );
  const moneyFormat = `£${moneyAmount}`;
  return moneyFormat;
}

/**
 * Converts an amount into cents (or pennies etc).
 * @param amount - The amount to convert, as a string or number.
 * @returns The amount in cents.
 * @example
 * toCents('$1.00');
 * // 100
 */
export function toCents(amount: string | number): number {
  const amountStr: string = amount.toString().replace(/[^0-9.]/g, "");
  if (amountStr.includes(".")) {
    let floatAmount: number = parseFloat(amountStr);
    floatAmount *= 100;
    return Math.round(floatAmount);
  }
  return parseInt((parseFloat(amountStr) * 100).toString());
}

export function formatMoney(amount: string, withCurrency = true) {
  const currencyCode = window.Shopify.currency.active || "USD";
  const parsedAmount = parseFloat(amount);
  const formatter = new Intl.NumberFormat(undefined, {
    style: withCurrency ? "currency" : "decimal",
    currency: currencyCode,
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });

  return formatter.format(parsedAmount);
}
